$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$Root = (Get-Location).Path
$OutDir = Join-Path $Root 'docs/miyake-yuko/img/tiktok-assets/variants-10-characters'
$TokaDir = Join-Path $Root 'docs/miyake-yuko/img/8mobby-toka'
New-Item -ItemType Directory -Path $OutDir -Force | Out-Null
function NewBrush($hex){ New-Object Drawing.SolidBrush ([Drawing.ColorTranslator]::FromHtml($hex)) }
function NewPen($hex,$w){ $pen=New-Object Drawing.Pen ([Drawing.ColorTranslator]::FromHtml($hex)), $w; $pen.StartCap='Round'; $pen.EndCap='Round'; return $pen }
function NewFont($name,$size,$style='Regular'){ try { New-Object Drawing.Font($name,$size,[Drawing.FontStyle]::$style,[Drawing.GraphicsUnit]::Pixel) } catch { New-Object Drawing.Font('Yu Gothic UI',$size,[Drawing.FontStyle]::$style,[Drawing.GraphicsUnit]::Pixel) } }
function DrawRound($g,$x,$y,$w,$h,$r,$fill,$stroke=$null){ $path=New-Object Drawing.Drawing2D.GraphicsPath; $d=$r*2; $path.AddArc($x,$y,$d,$d,180,90); $path.AddArc($x+$w-$d,$y,$d,$d,270,90); $path.AddArc($x+$w-$d,$y+$h-$d,$d,$d,0,90); $path.AddArc($x,$y+$h-$d,$d,$d,90,90); $path.CloseFigure(); if($fill){$g.FillPath($fill,$path)}; if($stroke){$g.DrawPath($stroke,$path)}; $path.Dispose() }
function DrawText($g,$text,$font,$brush,$x,$y,$w,$h,$align='Center'){ $sf=New-Object Drawing.StringFormat; $sf.Alignment=[Drawing.StringAlignment]::$align; $sf.LineAlignment='Center'; $sf.Trimming='EllipsisCharacter'; $g.DrawString($text,$font,$brush,(New-Object Drawing.RectangleF $x,$y,$w,$h),$sf); $sf.Dispose() }
function DrawImageFit($g,$path,$x,$y,$w,$h,$rot=0){ $img=[Drawing.Image]::FromFile($path); $scale=[Math]::Min($w/$img.Width,$h/$img.Height); $dw=$img.Width*$scale; $dh=$img.Height*$scale; $state=$g.Save(); $g.TranslateTransform($x+$w/2,$y+$h/2); if($rot -ne 0){$g.RotateTransform($rot)}; $g.DrawImage($img,-$dw/2,-$dh/2,$dw,$dh); $g.Restore($state); $img.Dispose() }
function Header($g,$sub){ DrawText $g '全キャラ紹介' $Title (NewBrush '#e94d7a') 70 34 940 72; DrawText $g $sub $Sub (NewBrush '#3b2929') 110 104 860 36 }
function Footer($g){ DrawRound $g 130 1418 820 42 21 (NewBrush '#fffdfb') (NewPen '#f39bb5' 2); DrawText $g '三宅裕子コラボ ビューティムード診断' $Foot (NewBrush '#e94d7a') 145 1420 790 38 }
function Card($g,$item,$x,$y,$w,$h,$color,$fill,$imgSize=138){ DrawRound $g $x $y $w $h 26 (NewBrush $fill) (NewPen $color 4); DrawImageFit $g $item.FullName ($x+12) ($y+12) $imgSize $imgSize 0; DrawText $g $item.BaseName $Label (NewBrush $color) ($x+$imgSize+24) ($y+20) ($w-$imgSize-38) 66 'Near'; DrawText $g 'Beauty Mood Mobby' $Small (NewBrush '#4a3636') ($x+$imgSize+24) ($y+88) ($w-$imgSize-38) 36 'Near' }
$Title=NewFont 'HGP創英角ﾎﾟｯﾌﾟ体' 64 'Bold'; $Sub=NewFont 'HG丸ｺﾞｼｯｸM-PRO' 24 'Bold'; $Label=NewFont 'HG丸ｺﾞｼｯｸM-PRO' 24 'Bold'; $Small=NewFont 'Comic Sans MS' 18 'Bold'; $Foot=NewFont 'HG丸ｺﾞｼｯｸM-PRO' 19 'Bold'
$Items=Get-ChildItem -LiteralPath $TokaDir -Filter '*.png' | Sort-Object Name
$Colors=@('#e94d7a','#ff8a25','#27a879','#219fb0','#6e63d8','#9b66de','#d29a39','#ef6f91')
for($v=1;$v -le 10;$v++){
  $bmp=New-Object Drawing.Bitmap 1080,1500; $g=[Drawing.Graphics]::FromImage($bmp); $g.SmoothingMode='AntiAlias'; $g.TextRenderingHint='AntiAliasGridFit'; $g.Clear([Drawing.ColorTranslator]::FromHtml('#fff4df'))
  switch($v){
    1 { Header $g '8タイプのモビーたち'; for($i=0;$i -lt 8;$i++){ $col=$i%2; $row=[math]::Floor($i/2); Card $g $Items[$i] (70+$col*490) (175+$row*290) 440 245 $Colors[$i] '#fffdfb' 150 } }
    2 { Header $g 'キャラクター図鑑'; DrawRound $g 70 170 940 1110 42 (NewBrush '#fffdfb') (NewPen '#f5b5c7' 5); for($i=0;$i -lt 8;$i++){ $x=105+($i%4)*220; $y=230+[math]::Floor($i/4)*430; DrawRound $g $x $y 180 330 32 (NewBrush '#fff7fb') (NewPen $Colors[$i] 3); DrawImageFit $g $Items[$i].FullName ($x+10) ($y+20) 160 190 0; DrawText $g $Items[$i].BaseName $Label (NewBrush $Colors[$i]) ($x+14) ($y+220) 152 74; DrawText $g 'Mobby' $Small (NewBrush '#4a3636') ($x+14) ($y+292) 152 26 } }
    3 { Header $g 'K-BEAUTY CAST'; DrawRound $g 58 170 964 1060 44 (NewBrush '#ffe8f0') (NewPen '#ffffff' 8); DrawText $g 'MOOD LINEUP' (NewFont 'Comic Sans MS' 38 'Bold') (NewBrush '#e94d7a') 90 200 900 60; for($i=0;$i -lt 8;$i++){ DrawImageFit $g $Items[$i].FullName (80+$i*118) (295+($i%2)*55) 128 160 (($i%3)-1)*5; DrawText $g $Items[$i].BaseName (NewFont 'HG丸ｺﾞｼｯｸM-PRO' 18 'Bold') (NewBrush $Colors[$i]) (58+$i*118) 485 150 54 } for($i=0;$i -lt 8;$i++){ Card $g $Items[$i] (95+($i%2)*465) (575+[math]::Floor($i/2)*165) 420 130 $Colors[$i] '#fffdfb' 92 } }
    4 { Header $g 'ステッカーシート'; for($i=0;$i -lt 8;$i++){ $x=80+(($i*237)%820); $y=190+(($i*163)%920); DrawRound $g $x $y 245 205 34 (NewBrush '#ffffff') (NewPen $Colors[$i] 4); DrawImageFit $g $Items[$i].FullName ($x+35) ($y+14) 170 138 (($i%5)-2)*7; DrawText $g $Items[$i].BaseName $Label (NewBrush $Colors[$i]) ($x+15) ($y+148) 215 42 } }
    5 { Header $g '韓国コスメ棚'; for($r=0;$r -lt 4;$r++){ DrawRound $g 80 (225+$r*255) 920 145 28 (NewBrush '#fffdfb') (NewPen '#d6b77b' 4) } for($i=0;$i -lt 8;$i++){ $x=105+($i%4)*225; $y=150+[math]::Floor($i/4)*510; DrawImageFit $g $Items[$i].FullName $x $y 175 180 0; DrawText $g $Items[$i].BaseName $Label (NewBrush $Colors[$i]) ($x-18) ($y+178) 210 48 } }
    6 { Header $g 'プロフィールカード'; for($i=0;$i -lt 8;$i++){ $x=75+($i%2)*490; $y=175+[math]::Floor($i/2)*285; DrawRound $g $x $y 440 240 36 (NewBrush '#f8fffb') (NewPen $Colors[$i] 4); DrawText $g ('No.'+($i+1).ToString('00')) (NewFont 'Comic Sans MS' 28 'Bold') (NewBrush $Colors[$i]) ($x+20) ($y+18) 110 36 'Near'; DrawImageFit $g $Items[$i].FullName ($x+30) ($y+58) 160 160 0; DrawText $g $Items[$i].BaseName $Label (NewBrush $Colors[$i]) ($x+205) ($y+60) 205 76 'Near'; DrawText $g 'Beauty Mood Type' $Small (NewBrush '#4a3636') ($x+205) ($y+138) 205 36 'Near' } }
    7 { Header $g 'フォトブース'; for($i=0;$i -lt 8;$i++){ $x=95+($i%4)*220; $y=180+[math]::Floor($i/4)*510; DrawRound $g $x $y 185 430 24 (NewBrush '#ffffff') (NewPen '#f3adc1' 4); DrawImageFit $g $Items[$i].FullName ($x+12) ($y+22) 160 210 (($i%2)*8-4); DrawText $g $Items[$i].BaseName $Label (NewBrush $Colors[$i]) ($x+15) ($y+260) 155 84; DrawText $g 'MOBBY' $Small (NewBrush '#4a3636') ($x+15) ($y+356) 155 32 } }
    8 { Header $g 'モビー相関マップ'; DrawRound $g 150 250 780 780 390 (NewBrush '#fffdfb') (NewPen '#f3adc1' 5); DrawImageFit $g $Items[0].FullName 390 500 300 300 0; for($i=0;$i -lt 8;$i++){ $angle=(-90+$i*45)*[Math]::PI/180; $x=475+[Math]::Cos($angle)*350; $y=600+[Math]::Sin($angle)*350; DrawRound $g ($x-115) ($y-70) 230 140 36 (NewBrush '#ffffff') (NewPen $Colors[$i] 3); DrawImageFit $g $Items[$i].FullName ($x-95) ($y-56) 85 85 0; DrawText $g $Items[$i].BaseName (NewFont 'HG丸ｺﾞｼｯｸM-PRO' 16 'Bold') (NewBrush $Colors[$i]) ($x-5) ($y-48) 105 90 'Near' } }
    9 { Header $g 'ミニアプリ一覧'; DrawRound $g 185 170 710 1080 48 (NewBrush '#ffffff') (NewPen '#f5a9bf' 5); DrawRound $g 230 215 620 82 41 (NewBrush '#ffe8f0') $null; DrawText $g 'Mobby Character List' (NewFont 'Comic Sans MS' 30 'Bold') (NewBrush '#e94d7a') 245 226 590 58; for($i=0;$i -lt 8;$i++){ Card $g $Items[$i] 225 (330+$i*105) 630 88 $Colors[$i] '#fffdfb' 72 } }
    10 { Header $g 'キャラクターステージ'; DrawRound $g 70 185 940 1040 42 (NewBrush '#f1fff4') (NewPen '#b7e1c5' 5); DrawText $g 'BEAUTY MOOD ALL STARS' (NewFont 'Comic Sans MS' 36 'Bold') (NewBrush '#27a879') 100 220 880 60; for($i=0;$i -lt 8;$i++){ DrawImageFit $g $Items[$i].FullName (55+$i*125) (825+($i%2)*35) 150 190 (($i%3)-1)*5; DrawText $g $Items[$i].BaseName (NewFont 'HG丸ｺﾞｼｯｸM-PRO' 18 'Bold') (NewBrush $Colors[$i]) (35+$i*125) 1045 170 54 } for($i=0;$i -lt 8;$i++){ DrawRound $g (105+($i%4)*220) (340+[math]::Floor($i/4)*190) 180 130 28 (NewBrush '#ffffff') (NewPen $Colors[$i] 3); DrawText $g $Items[$i].BaseName (NewFont 'HG丸ｺﾞｼｯｸM-PRO' 18 'Bold') (NewBrush $Colors[$i]) (118+($i%4)*220) (365+[math]::Floor($i/4)*190) 154 80 } }
  }
  Footer $g
  $file=Join-Path $OutDir ('all-characters-{0:D2}-code.png' -f $v)
  $bmp.Save($file,[Drawing.Imaging.ImageFormat]::Png)
  $prompt="Use case: infographic-diagram. Asset type: TikTok vertical post. Create an all-character introduction image, design version $v. Korean cute K-beauty mood, yellow-cream base, introduce all eight Mobby characters with their Japanese names: グルメモビー, 美容インフルエンサーモビー, 美容エディターモビー, 美容研究家モビー, 透明感モデルモビー, 韓ドラ女優モビー, 韓国アイドルモビー, 韓国コスメコンシェルジュモビー. Title exactly 全キャラ紹介. Use many cute transparent Mobby character images, varied layout, rounded kawaii Japanese typography, no diagnostic questions, no 8-type grid explanation, no watermark."
  Set-Content -LiteralPath (Join-Path $OutDir ('all-characters-{0:D2}-prompt.txt' -f $v)) -Value $prompt -Encoding UTF8
  $g.Dispose(); $bmp.Dispose()
}
Write-Output $OutDir
